declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    mermaid: {
      setMermaid: (attributes?: Partial<MermaidAttributes>) => ReturnType;
    };
  }
}

const FENCE_OPEN = /^ {0,3}(`{3,}|~{3,})[ \t]*mermaid(?:[ \t][^\n]*)?(?:\n|$)/;
const FENCE_OPEN_ANYWHERE = new RegExp(FENCE_OPEN.source, "m");

const longestRun = (value: string, char: string) => {
  let longest = 0;
  for (const run of value.match(new RegExp(`\\${char}+`, "g")) ?? []) {
    longest = Math.max(longest, run.length);
  }
  return longest;
};

export const Mermaid = Node.create<MermaidOptions>({
  addAttributes() {
    return {
      value: {
        default: null,
        parseHTML: (element) => element.textContent || null,
        rendered: false,
      },
    };
  },

  addCommands() {
    return {
      setMermaid:
        (attributes) =>
        ({ commands }) =>
          commands.insertContent({
            attrs: { value: attributes?.value ?? null },
            type: this.name,
          }),
    };
  },

  addNodeView() {
    return ReactNodeViewRenderer(MermaidView, {
      stopEvent: ({ event }) =>
        event.target instanceof Element &&
        event.target.closest(".ext-mermaid-frame") !== null,
    });
  },

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  atom: true,
  group: "block",

  markdownTokenName: "mermaid",

  markdownTokenizer: {
    level: "block",
    name: "mermaid",
    start: (src: string) => {
      const match = FENCE_OPEN_ANYWHERE.exec(src);
      return match ? match.index : -1;
    },
    tokenize: (src: string) => {
      const open = FENCE_OPEN.exec(src);
      const fence = open?.[1];
      if (!open || !fence) {
        return;
      }
      const afterOpen = src.slice(open[0].length);
      const close = new RegExp(
        `^ {0,3}\\${fence[0]}{${fence.length},}[ \\t]*$`,
        "m"
      ).exec(afterOpen);
      const body = close ? afterOpen.slice(0, close.index) : afterOpen;
      let rawLength = close
        ? open[0].length + close.index + close[0].length
        : src.length;
      if (src[rawLength] === "\n") {
        rawLength += 1;
      }
      return {
        raw: src.slice(0, rawLength),
        text: body.endsWith("\n") ? body.slice(0, -1) : body,
        type: "mermaid",
      };
    },
  },

  name: "mermaid",

  parseHTML() {
    return [{ tag: 'div[data-type="mermaid"]' }];
  },

  parseMarkdown: (token, helpers) =>
    helpers.createNode("mermaid", { value: token.text || null }),

  renderHTML({ HTMLAttributes, node }) {
    return [
      "div",
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        "data-type": "mermaid",
      }),
      ["pre", ["code", { class: "language-mermaid" }, node.attrs.value ?? ""]],
    ];
  },

  renderMarkdown: (node) => {
    const value = (node.attrs?.value as string | null) ?? "";
    const fence = "`".repeat(Math.max(3, longestRun(value, "`") + 1));
    return value
      ? `${fence}mermaid\n${value}\n${fence}`
      : `${fence}mermaid\n${fence}`;
  },
});

"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";

import { cn } from "../ui/utils";

type MermaidTheme = "dark" | "default";

const RENDER_DELAY = 300;
const CACHE_LIMIT = 100;

const cache = new Map<string, string>();
let queue: Promise<unknown> = Promise.resolve();
let renderCount = 0;

const settled = async (promise: Promise<unknown>) => {
  try {
    return await promise;
  } catch (error) {
    return error;
  }
};

const renderDiagram = (source: string, theme: MermaidTheme) => {
  const previous = queue;
  const task = (async () => {
    await previous;
    const { default: mermaid } = await import("mermaid");
    mermaid.initialize({
      securityLevel: "strict",
      startOnLoad: false,
      suppressErrorRendering: true,
      theme,
    });
    renderCount += 1;
    const { svg } = await mermaid.render(`ext-mermaid-${renderCount}`, source);
    return svg;
  })();
  queue = settled(task);
  return task;
};

const remember = (key: string, svg: string) => {
  cache.delete(key);
  cache.set(key, svg);
  if (cache.size > CACHE_LIMIT) {
    const oldest = cache.keys().next().value;
    if (oldest !== undefined) {
      cache.delete(oldest);
    }
  }
};

const subscribeToTheme = (onChange: () => void) => {
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributeFilter: ["class"],
    attributes: true,
  });
  return () => observer.disconnect();
};

const useMermaidTheme = (): MermaidTheme =>
  useSyncExternalStore(
    subscribeToTheme,
    () =>
      document.documentElement.classList.contains("dark") ? "dark" : "default",
    () => "default"
  );

interface RenderState {
  error?: string;
  key: string;
  svg?: string;
}

export interface MermaidPreviewProps {
  className?: string;
  value: string | null;
}

export const MermaidPreview = ({ className, value }: MermaidPreviewProps) => {
  const source = value?.trim() ?? "";
  const theme = useMermaidTheme();
  const key = `${theme}\n${source}`;
  const [state, setState] = useState<RenderState>(() => ({
    key,
    svg: cache.get(key),
  }));
  const rendered = useRef(Boolean(state.svg));

  useEffect(() => {
    if (!source) {
      return;
    }
    if (cache.has(key)) {
      rendered.current = true;
      return;
    }
    let cancelled = false;
    const timer = setTimeout(
      async () => {
        try {
          const svg = await renderDiagram(source, theme);
          remember(key, svg);
          if (!cancelled) {
            rendered.current = true;
            setState({ key, svg });
          }
        } catch (error) {
          if (!cancelled) {
            setState((current) => ({
              error:
                error instanceof Error
                  ? error.message
                  : "Failed to render diagram",
              key,
              svg: current.svg,
            }));
          }
        }
      },
      rendered.current ? RENDER_DELAY : 0
    );
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [key, source, theme]);

  if (!source) {
    return (
      <div
        className={cn(
          "ext-mermaid-empty flex min-h-32 items-center justify-center p-6 text-center text-xs text-muted-foreground",
          className
        )}
      >
        Empty diagram
      </div>
    );
  }

  const error = state.key === key ? state.error : undefined;
  const svg = cache.get(key) ?? state.svg;

  if (!svg) {
    return (
      <div className={cn("ext-mermaid-fallback", className)}>
        <output
          className={cn(
            "block px-4 pt-3 font-mono text-xs whitespace-pre-wrap",
            error ? "text-destructive" : "text-muted-foreground"
          )}
        >
          {error ?? "Rendering diagram..."}
        </output>
        <pre className="m-0 overflow-x-auto bg-transparent p-4 font-mono text-xs">
          <code>{source}</code>
        </pre>
      </div>
    );
  }

  return (
    <div className={cn("ext-mermaid-preview flex flex-col", className)}>
      {error && (
        <output className="ext-mermaid-error block px-4 pt-3 font-mono text-xs whitespace-pre-wrap text-destructive">
          {error}
        </output>
      )}
      <div
        className={cn(
          "ext-mermaid-svg flex justify-center overflow-auto p-4 [&_svg]:h-auto [&_svg]:max-w-full",
          error && "opacity-50"
        )}
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    </div>
  );
};

import type { SlashCommandItem } from "../core/types";

/** Slash command item for the `@editorcn/block-editor` menu. */
export const mermaidSlashCommandItem: SlashCommandItem = {
  command: ({ editor, range }) => {
    if (!editor.can().setMermaid()) {
      return;
    }
    editor.chain().focus().deleteRange(range).setMermaid().run();
  },
  description: "Draw a flowchart, sequence or other diagram with Mermaid.",
  id: "mermaid",
  keywords: ["mermaid", "diagram", "flowchart", "chart", "sequence", "graph"],
  title: "Diagram",
};

"use client";

import { NodeViewWrapper } from "@tiptap/react";
import type { ReactNodeViewProps } from "@tiptap/react";
import {
  Check,
  Code,
  Columns2,
  Copy,
  Eye,
  Pencil,
  Trash2,
  Workflow,
} from "lucide-react";
import { useEffect, useState } from "react";
import type { KeyboardEvent, ReactNode } from "react";

import { useEditable } from "../core/editor-state";
import { Button } from "../ui/button";
import { cn } from "../ui/utils";
import { MermaidPreview } from "./preview";

type Layout = "code" | "split" | "preview";

const PLACEHOLDER = `graph TD
  A[Start] --> B{Is it working?}
  B -->|Yes| C[Ship it]
  B -->|No| D[Debug]
  D --> B`;

const LAYOUTS: { icon: ReactNode; label: string; value: Layout }[] = [
  { icon: <Code />, label: "Code", value: "code" },
  { icon: <Columns2 />, label: "Split", value: "split" },
  { icon: <Eye />, label: "Preview", value: "preview" },
];

const IS_MAC =
  typeof navigator !== "undefined" &&
  /Mac|iPhone|iPad/.test(navigator.userAgent);

const ICON_BUTTON_CLASS =
  "size-7 rounded-md text-muted-foreground hover:bg-muted hover:text-foreground [&>svg]:size-3.5";

const KBD_CLASS =
  "rounded-md border border-border/60 bg-background px-1.5 py-px font-sans text-[0.6875rem] text-muted-foreground";

const useCopy = (text: string) => {
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!copied) {
      return;
    }
    const timer = setTimeout(() => setCopied(false), 2000);
    return () => clearTimeout(timer);
  }, [copied]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
    } catch {
      setCopied(false);
    }
  };

  return { copied, copy };
};

interface MermaidCardProps {
  editable: boolean;
  onDelete: () => void;
  onEdit: () => void;
  selected: boolean;
  value: string;
}

const MermaidCard = ({
  editable,
  onDelete,
  onEdit,
  selected,
  value,
}: MermaidCardProps) => {
  const { copied, copy } = useCopy(value);

  return (
    <div
      className={cn(
        "ext-mermaid-box group/mermaid relative rounded-xl border border-border/60 bg-card select-none [transition:box-shadow_150ms_ease-out]",
        selected && "border-ring ring-[3px] ring-ring/30 ring-inset"
      )}
      contentEditable={false}
      onDoubleClick={editable ? onEdit : undefined}
    >
      <div className="ext-mermaid-actions absolute top-2 right-2 z-10 flex items-center gap-0.5 rounded-lg border border-border/60 bg-background p-0.5 opacity-0 shadow-[0_8px_30px_-12px_rgb(0_0_0/0.15)] [transition:opacity_150ms_ease-out] group-hover/mermaid:opacity-100 focus-within:opacity-100 motion-reduce:transition-none">
        <Button
          size="icon-sm"
          className={ICON_BUTTON_CLASS}
          aria-label="Copy source"
          tooltip={copied ? "Copied" : "Copy source"}
          disabled={!value}
          onClick={copy}
        >
          {copied ? <Check /> : <Copy />}
        </Button>
        {editable && (
          <>
            <Button
              size="icon-sm"
              className={ICON_BUTTON_CLASS}
              aria-label="Edit diagram"
              tooltip="Edit"
              onClick={onEdit}
            >
              <Pencil />
            </Button>
            <div className="mx-0.5 h-4 w-px bg-border" />
            <Button
              size="icon-sm"
              className={cn(
                ICON_BUTTON_CLASS,
                "hover:bg-destructive/10 hover:text-destructive"
              )}
              aria-label="Delete diagram"
              tooltip="Delete"
              onClick={onDelete}
            >
              <Trash2 />
            </Button>
          </>
        )}
      </div>
      <MermaidPreview value={value} className="min-h-40 px-6 py-8" />
    </div>
  );
};

export const MermaidView = ({
  deleteNode,
  editor,
  node,
  selected,
  updateAttributes,
}: ReactNodeViewProps<HTMLDivElement>) => {
  const editable = useEditable(editor);
  const value = (node.attrs.value as string | null) ?? "";
  const [editing, setEditing] = useState(() => editable && !value);
  const [draft, setDraft] = useState(value);
  const [layout, setLayout] = useState<Layout>("split");
  const { copied, copy } = useCopy(draft);

  const isEditing = editing && editable;
  const lines = draft ? draft.split("\n").length : 0;
  const dirty = draft !== value;

  const startEditing = () => {
    setDraft(value);
    setEditing(true);
  };

  const apply = () => {
    updateAttributes({ value: draft.trim() ? draft : null });
    setEditing(false);
  };

  const cancel = () => {
    if (value) {
      setDraft(value);
      setEditing(false);
    } else {
      deleteNode();
    }
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
      event.preventDefault();
      apply();
    } else if (event.key === "Escape") {
      event.preventDefault();
      cancel();
    }
  };

  if (!isEditing) {
    return (
      <NodeViewWrapper className="ext-mermaid my-3" data-type="mermaid">
        <MermaidCard
          editable={editable}
          selected={selected}
          value={value}
          onDelete={deleteNode}
          onEdit={startEditing}
        />
      </NodeViewWrapper>
    );
  }

  const showCode = layout !== "preview";
  const showPreview = layout !== "code";

  return (
    <NodeViewWrapper className="ext-mermaid my-3" data-type="mermaid">
      <div
        className="ext-mermaid-frame @container/mermaid rounded-xl border border-border/60 bg-muted/50 p-1 select-none"
        contentEditable={false}
      >
        <div className="ext-mermaid-header flex items-center justify-between gap-2 py-1 pr-1 pl-2.5">
          <div className="flex min-w-0 items-center gap-2">
            <Workflow className="size-3.5 shrink-0 text-muted-foreground" />
            <span className="text-sm font-medium text-foreground">Diagram</span>
            <span className="hidden text-xs text-muted-foreground tabular-nums @sm/mermaid:inline">
              {lines} {lines === 1 ? "line" : "lines"}
            </span>
          </div>
          <div className="flex items-center gap-1">
            <fieldset
              className="ext-mermaid-layout m-0 flex h-8 min-w-0 items-center gap-0.5 rounded-lg border border-border/60 bg-background p-0.5"
              aria-label="Layout"
            >
              {LAYOUTS.map((option) => (
                <Button
                  key={option.value}
                  className={cn(
                    "h-7 gap-1.5 rounded-md px-2 text-xs font-medium text-muted-foreground hover:bg-muted/60 hover:text-foreground [&>svg]:size-3.5",
                    layout === option.value &&
                      "bg-muted text-foreground hover:bg-muted"
                  )}
                  active={layout === option.value}
                  aria-label={option.label}
                  onClick={() => setLayout(option.value)}
                >
                  {option.icon}
                  <span className="hidden @lg/mermaid:inline">
                    {option.label}
                  </span>
                </Button>
              ))}
            </fieldset>
            <Button
              size="icon-sm"
              className={cn(ICON_BUTTON_CLASS, "size-8")}
              aria-label="Copy source"
              tooltip={copied ? "Copied" : "Copy source"}
              disabled={!draft}
              onClick={copy}
